1	// Unit tests for the oracle differential compare (driver/state_diff.hpp).
2	//
3	// Policy under test (docs/archive/verify_oracle.md): strictly compare what vsim's exit
4	// drain freshly reads (pc, GPRs; FPRs under FLAG_FP; V CSRs + vreg bytes
5	// under FLAG_V) plus the identity fields; SKIP the passthrough M-CSRs/PMP
6	// (vsim copies them from QEMU1's entry snapshot, so they cannot equal the
7	// oracle's exit values by construction); MASK the counters (engines count
8	// differently by design).
9	#include "state_diff.hpp"
10	
11	#include "hybrid/state_abi.h"
12	#include "test_check.hpp"
13	
14	using namespace andes_sim;
15	
16	namespace {
17	
18	// A fully populated reference state (FP + V live).
19	hybrid_state_v1 base_state() {
20	  hybrid_state_v1 s{};
21	  s.magic = HYBRID_STATE_MAGIC;
22	  s.version = HYBRID_STATE_VERSION;
23	  s.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_FP | HYBRID_FLAG_V;
24	  s.hart_id = 0;
25	  s.priv = 3;
26	  s.pc = 0x100240;
27	  for (int i = 0; i < 32; ++i) s.gpr[i] = 0x1000 + i;
28	  s.gpr[0] = 0;
29	  for (int i = 0; i < 32; ++i) s.fpr[i] = 0x2000 + i;
30	  s.fcsr = 0x21;  // frm=RTZ | fflags=NX (L20)
31	  s.vstart = 0;
32	  s.vtype = 0xd0;
33	  s.vl = 16;
34	  s.vlenb = 64;
35	  s.vxsat = 0;
36	  s.vxrm = 1;
37	  s.vcsr = 2;
38	  for (int i = 0; i < 32 * HYBRID_VLEN_BYTES_MAX; ++i)
39	    s.vreg[i] = static_cast<uint8_t>(i * 7);
40	  s.mcycle = 1000;
41	  s.minstret = 900;
42	  s.mstatus = 0xa00002200ull;
43	  s.mepc = 0x5555;
44	  s.satp = 0x9999;
45	  s.pmpaddr[3] = 0x77;
46	  return s;
47	}
48	
49	// Fields strictly compared for a FP+V state (hybrid policy): 6 identity/pc +
50	// 4 mepc/mcause/mtval/mie (L24) + 1 mscratch (L23) + 32 gpr + 32 fpr +
51	// fcsr (L20) + 7 V scalars + 32 vregs.
52	constexpr int kFullCompared = 6 + 4 + 1 + 32 + 33 + 7 + 32;
53	
54	// An RV64-only state with the Andes block live (HYBRID_FLAG_ANDES), every
55	// transported Andes CSR carrying a distinct sentinel.
56	hybrid_state_v1 andes_state() {
57	  hybrid_state_v1 s{};
58	  s.magic = HYBRID_STATE_MAGIC;
59	  s.version = HYBRID_STATE_VERSION;
60	  s.flags = HYBRID_FLAG_RV64 | HYBRID_FLAG_ANDES;
61	  s.priv = 3;
62	  s.pc = 0x100240;
63	  for (int i = 0; i < 32; ++i) s.gpr[i] = 0x1000 + i;
64	  s.gpr[0] = 0;
65	  uint64_t v = 0xA000;
66	#define X(field, addr, name) s.andes.field = v++;
67	  HYBRID_ANDES_CSR_LIST(X)
68	#undef X
69	  for (int i = 0; i < HYBRID_PMA_CFG_NUM; ++i) s.andes.pmacfg[i] = 0xB000 + i;
70	  for (int i = 0; i < HYBRID_PMA_ADDR_NUM; ++i) s.andes.pmaaddr[i] = 0xC000 + i;
71	  return s;
72	}
73	
74	// Andes block compared fields: 13 scalars - 4 verify-excluded (msp_bound,
75	// msp_base, milmb, mdlmb; engine-reset-divergent, see state_diff.cpp) +
76	// pmacfg[2] + pmaaddr[16] = 27.
77	constexpr int kAndesCompared =
78	    (13 - 4) + HYBRID_PMA_CFG_NUM + HYBRID_PMA_ADDR_NUM;
79	
80	}  // namespace
81	
82	int main() {
83	  {  // identical states -> ok, full field count
84	    const hybrid_state_v1 a = base_state();
85	    const DiffReport r = diff_states(a, a);
86	    CHECK(r.ok());
87	    CHECK(r.compared == kFullCompared);
88	  }
89	
90	  {  // a GPR mismatch is caught and named
91	    const hybrid_state_v1 ref = base_state();
92	    hybrid_state_v1 got = ref;
93	    got.gpr[5] = 0xdead;
94	    const DiffReport r = diff_states(ref, got);
95	    CHECK(!r.ok());
96	    CHECK(r.diffs.size() == 1);
97	    CHECK(r.diffs[0].field == "x5");
98	    CHECK(r.diffs[0].ref == 0x1005);
99	    CHECK(r.diffs[0].got == 0xdead);
100	  }
101	
102	  {  // pc mismatch
103	    const hybrid_state_v1 ref = base_state();
104	    hybrid_state_v1 got = ref;
105	    got.pc = ref.pc + 4;
106	    const DiffReport r = diff_states(ref, got);
107	    CHECK(r.diffs.size() == 1);
108	    CHECK(r.diffs[0].field == "pc");
109	  }
110	
111	  {  // counters are masked: mcycle/minstret may differ
112	    const hybrid_state_v1 ref = base_state();
113	    hybrid_state_v1 got = ref;
114	    got.mcycle = 999999;
115	    got.minstret = 888888;
116	    CHECK(diff_states(ref, got).ok());
117	  }
118	
119	  {  // passthrough M-CSRs/PMP are skipped, not compared. mepc/mcause/mtval/mie
120	     // left this set in L24 and mscratch in L23 (they now round-trip and are
121	     // strictly compared); mip stays here (hardware-driven pending bits).
122	    const hybrid_state_v1 ref = base_state();
123	    hybrid_state_v1 got = ref;
124	    got.mstatus = 0x1;
125	    got.mtvec = 0x3;
126	    got.medeleg = 0x7;
127	    got.mideleg = 0x8;
128	    got.mip = 0x9;
129	    got.satp = 0xb;
130	    got.pmpcfg[0] = 0xc;
131	    got.pmpaddr[63] = 0xd;
132	    CHECK(diff_states(ref, got).ok());
133	  }
134	
135	  {  // L23: mscratch round-trips (restored at resume, re-read at drain), so the
136	     // hybrid verify policy compares it.
137	    hybrid_state_v1 ref = base_state();
138	    ref.flags = HYBRID_FLAG_RV64;
139	    hybrid_state_v1 got = ref;
140	    got.mscratch = 0xdead;
141	    const DiffReport hy = diff_states(ref, got);
142	    CHECK(!hy.ok());
143	    CHECK(hy.diffs.size() == 1);
144	    CHECK(hy.diffs[0].field == "mscratch");
145	  }
146	
147	  {  // L24: mepc/mcause/mtval/mie round-trip through the hybrid handoff, so the
148	     // hybrid policy compares each. mip is restored + re-read but EXCLUDED from
149	     // verify (its pending bits are hardware/platform-driven and diverge
150	     // between QEMU's functional clock and vsim's cycle-accurate one).
151	    hybrid_state_v1 ref = base_state();
152	    ref.flags = HYBRID_FLAG_RV64;
153	    {
154	      hybrid_state_v1 got = ref;
155	      got.mepc = 0xbad;
156	      const DiffReport hy = diff_states(ref, got);
157	      CHECK(hy.diffs.size() == 1);
158	      CHECK(hy.diffs[0].field == "mepc");
159	    }
160	    {
161	      hybrid_state_v1 got = ref;
162	      got.mtval = 0xbad;
163	      const DiffReport hy = diff_states(ref, got);
164	      CHECK(hy.diffs.size() == 1);
165	      CHECK(hy.diffs[0].field == "mtval");
166	    }
167	    {
168	      hybrid_state_v1 got = ref;
169	      got.mie = 0xbad;
170	      const DiffReport hy = diff_states(ref, got);
171	      CHECK(hy.diffs.size() == 1);
172	      CHECK(hy.diffs[0].field == "mie");
173	    }
174	    {  // mip excluded from verify.
175	      hybrid_state_v1 got = ref;
176	      got.mip = 0xbad;
177	      CHECK(diff_states(ref, got).ok());
178	    }
179	  }
180	
181	  {  // no FLAG_FP -> FPRs not compared, count shrinks
182	    hybrid_state_v1 ref = base_state();
183	    ref.flags = HYBRID_FLAG_RV64;
184	    hybrid_state_v1 got = ref;
185	    got.fpr[7] = 0xbad;
186	    got.vtype = 0xbad;  // V block also off
187	    const DiffReport r = diff_states(ref, got);
188	    CHECK(r.ok());
189	    // identity/pc + gpr + mscratch (L23) + mepc/mcause/mtval/mie (L24)
190	    CHECK(r.compared == 6 + 32 + 1 + 4);
191	  }
192	
193	  {  // FPR mismatch under FLAG_FP
194	    const hybrid_state_v1 ref = base_state();
195	    hybrid_state_v1 got = ref;
196	    got.fpr[31] = 0;
197	    const DiffReport r = diff_states(ref, got);
198	    CHECK(r.diffs.size() == 1);
199	    CHECK(r.diffs[0].field == "f31");
200	  }
201	
202	  {  // fcsr mismatch under FLAG_FP (L20)
203	    const hybrid_state_v1 ref = base_state();
204	    hybrid_state_v1 got = ref;
205	    got.fcsr = 0;  // restore lost: vsim drained the reset value
206	    const DiffReport r = diff_states(ref, got);
207	    CHECK(r.diffs.size() == 1);
208	    CHECK(r.diffs[0].field == "fcsr");
209	  }
210	
211	  {  // V scalar CSR mismatch
212	    const hybrid_state_v1 ref = base_state();
213	    hybrid_state_v1 got = ref;
214	    got.vl = 8;
215	    const DiffReport r = diff_states(ref, got);
216	    CHECK(r.diffs.size() == 1);
217	    CHECK(r.diffs[0].field == "vl");
218	  }
219	
220	  {  // vreg byte mismatch names the register and byte offset
221	    const hybrid_state_v1 ref = base_state();
222	    hybrid_state_v1 got = ref;
223	    got.vreg[3 * HYBRID_VLEN_BYTES_MAX + 7] ^= 0xff;
224	    const DiffReport r = diff_states(ref, got);
225	    CHECK(r.diffs.size() == 1);
226	    CHECK(r.diffs[0].field == "v3[7]");
227	    CHECK(r.diffs[0].ref == ref.vreg[3 * HYBRID_VLEN_BYTES_MAX + 7]);
228	  }
229	
230	  {  // identity mismatch (flags) is caught
231	    const hybrid_state_v1 ref = base_state();
232	    hybrid_state_v1 got = ref;
233	    got.flags = HYBRID_FLAG_RV64;
234	    const DiffReport r = diff_states(ref, got);
235	    CHECK(!r.ok());
236	    bool saw_flags = false;
237	    for (const FieldDiff& d : r.diffs) saw_flags |= d.field == "flags";
238	    CHECK(saw_flags);
239	  }
240	
241	  {  // multiple mismatches all reported
242	    const hybrid_state_v1 ref = base_state();
243	    hybrid_state_v1 got = ref;
244	    got.gpr[1] = 1;
245	    got.gpr[2] = 2;
246	    got.pc = 4;
247	    CHECK(diff_states(ref, got).diffs.size() == 3);
248	  }
249	
250	  {  // field count for an RV64-only state: identity/pc + gpr + the round-trip
251	     // M-CSRs mscratch (L23) and mepc/mcause/mtval/mie (L24) = 5 extra.
252	    hybrid_state_v1 ref = base_state();
253	    ref.flags = HYBRID_FLAG_RV64;  // no FP/V to keep the count simple
254	    const DiffReport r = diff_states(ref, ref);
255	    CHECK(r.compared == 6 + 32 + 5);  // + mscratch/mepc/mcause/mtval/mie
256	    CHECK(r.ok());
257	  }
258	
259	  {  // mcause mismatch caught (L24: hybrid compares it)
260	    hybrid_state_v1 ref = base_state();
261	    ref.flags = HYBRID_FLAG_RV64;
262	    hybrid_state_v1 got = ref;
263	    got.mcause = 2;  // illegal-instruction vs ref's 0
264	    const DiffReport r = diff_states(ref, got);
265	    CHECK(!r.ok());
266	    CHECK(r.diffs.size() == 1);
267	    CHECK(r.diffs[0].field == "mcause");
268	    CHECK(r.diffs[0].got == 2);
269	  }
270	
271	  {  // mstatus stays EXCLUDED (dirty/impl-defined bits).
272	    hybrid_state_v1 ref = base_state();
273	    ref.flags = HYBRID_FLAG_RV64;
274	    hybrid_state_v1 got = ref;
275	    got.mstatus = 0x1;
276	    CHECK(diff_states(ref, got).ok());
277	  }
278	
279	  {  // Andes block (v3): identical states match, with the full extra field count.
280	    const hybrid_state_v1 a = andes_state();
281	    const DiffReport r = diff_states(a, a);
282	    CHECK(r.ok());
283	    CHECK(r.compared == 6 + 32 + 5 + kAndesCompared);  // base RV64 set + andes
284	  }
285	
286	  {  // each representative COMPARED Andes CSR is caught + named (milmb/mdlmb are
287	     // verify-excluded -- see the dedicated block above)
288	    const hybrid_state_v1 ref = andes_state();
289	    const std::pair<const char*, uint64_t hybrid_andes_csr::*> probes[] = {
290	      {"uitb", &hybrid_andes_csr::uitb},            // F1 CoDense
291	      {"jvt", &hybrid_andes_csr::jvt},              // F1 Zcmt
292	      {"mxstatus", &hybrid_andes_csr::mxstatus},    // F2
293	      {"ucode", &hybrid_andes_csr::ucode},          // F4 DSP
294	      {"mecc_code", &hybrid_andes_csr::mecc_code},  // F5 memory system
295	      {"mpft_ctl", &hybrid_andes_csr::mpft_ctl},    // F6
296	      {"mhsp_ctl", &hybrid_andes_csr::mhsp_ctl},    // F7
297	      {"mcountermask_m", &hybrid_andes_csr::mcountermask_m},  // F8
298	    };
299	    for (const auto& [name, member] : probes) {
300	      hybrid_state_v1 got = ref;
301	      got.andes.*member ^= 0xDEAD;
302	      const DiffReport r = diff_states(ref, got);
303	      CHECK(r.diffs.size() == 1);
304	      CHECK(r.diffs[0].field == name);
305	    }
306	  }
307	
308	  {  // F3 PMA: a pmacfg and a pmaaddr mismatch are each caught + named
309	    const hybrid_state_v1 ref = andes_state();
310	    {
311	      hybrid_state_v1 got = ref;
312	      got.andes.pmacfg[1] = 0xbad;
313	      const DiffReport r = diff_states(ref, got);
314	      CHECK(r.diffs.size() == 1);
315	      CHECK(r.diffs[0].field == "pmacfg1");
316	    }
317	    {
318	      hybrid_state_v1 got = ref;
319	      got.andes.pmaaddr[5] = 0xbad;
320	      const DiffReport r = diff_states(ref, got);
321	      CHECK(r.diffs.size() == 1);
322	      CHECK(r.diffs[0].field == "pmaaddr5");
323	    }
324	  }
325	
326	  {  // without HYBRID_FLAG_ANDES the block is NOT compared (zero or stale)
327	    hybrid_state_v1 ref = andes_state();
328	    ref.flags = HYBRID_FLAG_RV64;  // clear ANDES
329	    hybrid_state_v1 got = ref;
330	    got.andes.uitb = 0xbad;
331	    got.andes.pmaaddr[0] = 0xbad;
332	    CHECK(diff_states(ref, got).ok());
333	  }
334	
335	  {  // msp_bound/msp_base are engine-reset-divergent (QEMU resets them to
336	     // all-ones; a vsim core without HW stack protection drains 0), so verify
337	     // EXCLUDES them like mip -- still transported, just not strict-compared.
338	    const hybrid_state_v1 ref = andes_state();
339	    hybrid_state_v1 got = ref;
340	    got.andes.msp_bound = 0;
341	    got.andes.msp_base = 0;
342	    CHECK(diff_states(ref, got).ok());
343	  }
344	
345	  {  // milmb/mdlmb are the ILM/DLM base+enable CSRs. The base address matches
346	     // across engines, but the enable bit (bit 0) is HW-presence state: the vsim
347	     // RTL has the local memories and drains EN=1, while QEMU models none and
348	     // drains EN=0. Same engine-reset-divergent class as msp_bound/msp_base, so
349	     // verify EXCLUDES them -- still transported, just not strict-compared.
350	    const hybrid_state_v1 ref = andes_state();
351	    hybrid_state_v1 got = ref;
352	    got.andes.milmb ^= 0x1;  // flip the enable bit only (base unchanged)
353	    got.andes.mdlmb ^= 0x1;
354	    CHECK(diff_states(ref, got).ok());
355	  }
356	
357	  {  // S4 Andes caps: a CSR the engine does NOT implement is verify-excluded.
358	     // vsim never restored/re-read it (the resume/drain gate), so comparing it
359	     // against the QEMU oracle would false-diff. The supported list comes from
360	     // the engine's --describe andes_csrs.
361	    const hybrid_state_v1 ref = andes_state();
362	    hybrid_state_v1 got = ref;
363	    got.andes.ucode ^= 0xDEAD;
364	
365	    // engine lacks ucode -> excluded, no diff.
366	    CHECK(diff_states(ref, got, {"uitb", "milmb"}).ok());
367	    // engine has ucode -> the diff IS reported.
368	    const DiffReport in = diff_states(ref, got, {"ucode"});
369	    CHECK(in.diffs.size() == 1);
370	    CHECK(in.diffs[0].field == "ucode");
371	    // empty list (default) = compare all (state-diff subcommand / no engine info).
372	    CHECK(diff_states(ref, got).diffs.size() == 1);
373	  }
374	
375	  {  // S4 Andes caps: the PMA block is excluded via the "pmaaddr"/"pmacfg" markers
376	    const hybrid_state_v1 ref = andes_state();
377	    hybrid_state_v1 got = ref;
378	    got.andes.pmaaddr[0] ^= 0xDEAD;
379	    CHECK(diff_states(ref, got, {"uitb"}).ok());  // no PMA support -> excluded
380	    const DiffReport in = diff_states(ref, got, {"pmaaddr"});
381	    CHECK(in.diffs.size() == 1);
382	    CHECK(in.diffs[0].field == "pmaaddr0");
383	  }
384	
385	  return andes_sim::test::report("state_diff");
386	}
